"""Static offline viewer: no remote assets, network calls, private body display."""
from pathlib import Path
import json, html

def build(out:Path,destination:Path):
    rows=[json.loads(x) for x in (out/'strategies_1728.jsonl').read_text().splitlines() if x]
    meta=json.loads((out/'meta145.json').read_text())
    spheres=json.loads((out/'sphere_144.json').read_text())
    # Never embed the original 2.2MB source registry, source descriptions, or corpus.
    slim=[{'id':x['sourceCoordinate'],'sphere':x['sphere'],'family':x['policy']['family_bonus'],'dissent':x['policy']['dissent_bonus'],
           'threshold':x['policy']['min_score'],'objective':x['development']['objective'],
           'sourceRecordDigest':x['sourceRecordSha256'][:12]} for x in rows]
    payload=json.dumps({'meta':meta,'spheres':spheres,'strategies':slim},separators=(',',':')).replace('<','\\u003c')
    shell=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas Neural META145 | Local Strategy Observatory</title><style>
:root{color-scheme:dark;--bg:#091823;--fg:#ebf6fc;--mute:#afc0ca;--border:#285164;--blue:#6fcaff;--green:#a4e7c7}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 78% 2%,#153b50,transparent 44%),var(--bg);font:15px system-ui,sans-serif;color:var(--fg)}main{max-width:1160px;margin:auto;padding:24px}h1{letter-spacing:-.045em;font-size:clamp(24px,4vw,43px)}header p{max-width:800px;color:var(--mute);line-height:1.6}small{color:var(--mute)}.eyebrow{color:var(--green);font-weight:700;letter-spacing:.17em;font-size:11px;text-transform:uppercase}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.stat{border:1px solid var(--border);background:#0e2633;border-radius:12px;padding:16px}.stat strong{display:block;font-size:28px;color:var(--green)}.stat span{color:var(--mute);font-size:12px}.panel{border:1px solid var(--border);border-radius:12px;padding:17px;margin:16px 0;background:#0b1e29}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.controls>*{background:#091721;border:1px solid #51758a;color:var(--fg);padding:10px;border-radius:8px;min-width:180px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.item{border:1px solid var(--border);border-radius:9px;padding:12px;text-align:left;color:var(--fg);background:#102d3b;cursor:pointer}.item:hover,.item:focus{outline:2px solid var(--green)}.item b{display:block;color:var(--blue)}.item em{font-style:normal;color:var(--mute);font-size:12px}.detail{background:#0e2c36;border:1px solid #438c93;border-radius:10px;padding:12px;margin:12px 0;white-space:pre-wrap;overflow-wrap:anywhere}button.more{background:#276175;color:white;border:0;padding:10px 16px;border-radius:8px;cursor:pointer}.muted{color:var(--mute)}.hold{font-size:13px;border-left:3px solid #ebcc91;padding:10px 14px;background:#3c3425}.row{display:flex;gap:20px;flex-wrap:wrap}.row>div{flex:1;min-width:220px}@media(max-width:700px){main{padding:14px}.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:repeat(2,1fr)}.controls>*{width:100%}}@media(max-width:410px){.grid{grid-template-columns:1fr}}
</style></head><body><main><header><div class="eyebrow">PRIVATE · OFFLINE · NOT HOSTED</div><h1>Neural META145 · Evidence-first Strategy Observatory</h1><p>1,728 finite strategy configurations keyed by original Ariadne coordinates, 144 source-addressed Sphere selections, 12 House rollups and one synthetic holdout synthesis. These addresses are experimental indices, not claims about node-level model expertise or true meaning.</p></header><section class="stats" id="stats"></section><section class="panel"><h2>Development and held-out performance</h2><div class="row" id="comparisons"></div><p class="hold">These numbers refer ONLY to generated synthetic evidence scenarios. No BGE weights, MICA's once-consumed silver panel, natural-language translation, authenticated source bodies, hosted rights or new model training were used.</p></section><section class="panel"><h2>All 1,728 strategy records</h2><div class="controls"><input id="q" type="search" placeholder="Search exact HSN" aria-label="Search strategies"><select id="house" aria-label="Filter house"><option value="">All 12 Houses</option></select><select id="sphere" aria-label="Filter sphere"><option value="">All 144 Spheres</option></select></div><p class="muted" id="count"></p><div id="detail" class="detail" hidden tabindex="-1"></div><div class="grid" id="results"></div><div style="padding:16px 0"><button id="next" class="more">Show next 48</button></div></section><section class="panel"><h2>Release gates</h2><p class="muted">This pure sidecar can be attached to MICA's existing pretrained-entry producer when its exact owner-held API and authorized host source/rights port are available. It cannot verify live READ/RETURN, current source grants, unknown family lineage or general neural transfer itself. Promote no corpus content or accepted relation from this offline artifact.</p></section></main><script id="payload" type="application/json">__DATA__</script><script>
'use strict'; const data=JSON.parse(document.getElementById('payload').textContent);const list=data.strategies, meta=data.meta;const $=id=>document.getElementById(id);for(let i=1;i<=12;i++){$('house').add(new Option('H'+String(i).padStart(2,'0'),'H'+String(i).padStart(2,'0')))}const uniq=[...new Set(list.map(x=>x.sphere))];for(const s of uniq)$('sphere').add(new Option(s,s));
$('stats').innerHTML=[['Configurations',list.length],['Sphere winners',data.spheres.length],['House rollups',meta.houseRollups],['Synthetic source leaks',meta.selectedHeldout.sourceLeakCount]].map(x=>`<div class="stat"><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('');
$('comparisons').innerHTML=[['Baseline',meta.baselineHeldout],['META145-selected',meta.selectedHeldout]].map(([title,m])=>`<div><h3>${title}</h3><p>Independent roots/query: <b>${m.independentRootsPerQuery}</b></p><p>Relevant roots/query: <b>${m.targetRootsPerQuery}</b></p><p>Dissent retained: <b>${Math.round(m.dissentRetention*100)}%</b></p><p>Correct abstention: <b>${Math.round(m.correctAbstention*100)}%</b></p></div>`).join('');
let shown=48, filtered=[];function refresh(){const q=$('q').value.trim().toUpperCase(),h=$('house').value,s=$('sphere').value;filtered=list.filter(x=>(!q||x.id.includes(q))&&(!h||x.id.startsWith(h+'.'))&&(!s||x.sphere===s));$('count').textContent=`${filtered.length} matching configurations; ${Math.min(shown,filtered.length)} visible. All remain simulated.`;$('results').replaceChildren();for(const x of filtered.slice(0,shown)){const b=document.createElement('button');b.className='item';b.type='button';const t=document.createElement('b');t.textContent=x.id;const e=document.createElement('em');e.textContent=`dev objective: ${x.objective.toFixed(3)}`;b.append(t,e);b.addEventListener('click',()=>{const v=$('detail');v.hidden=false;v.textContent=JSON.stringify(x,null,2);v.focus()});$('results').append(b)}$('next').hidden=shown>=filtered.length;}
for(const id of ['q','house','sphere'])$(id).addEventListener(id==='q'?'input':'change',()=>{shown=48;refresh()});$('next').addEventListener('click',()=>{shown+=48;refresh()});refresh();
</script></body></html>'''
    destination.write_text(shell.replace('__DATA__',payload),encoding='utf8')
    return {'strategies':len(slim),'spheres':len(spheres),'size':destination.stat().st_size}

if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('--out',required=True);p.add_argument('--dest',required=True);a=p.parse_args()
    print(build(Path(a.out),Path(a.dest)))
